// Normalizador de entradas via Webhook (Amazon, ML, Shopee, Lomadee, Manual)
const item = $input.first().json;
const body = item.body || item;
const rawUrl = body.url || body.link || "";
const amazonTag = $env.AMAZON_ASSOCIATE_TAG || "tenisofertas-20";

let plataforma = body.plataforma || "manual";
let linkAfiliado = rawUrl;
let asin = null;

// 1. Identificar e processar Amazon
if (rawUrl.includes("amazon.com") || rawUrl.includes("amzn.to")) {
  plataforma = "amazon";
  const asinMatch = rawUrl.match(/(?:dp|gp\/product)\/([A-Z0-9]{10})/i);
  if (asinMatch) {
    asin = asinMatch[1];
    linkAfiliado = `https://www.amazon.com.br/dp/${asin}?tag=${amazonTag}`;
  }
}
// 2. Identificar Mercado Livre
else if (rawUrl.includes("mercadolivre.com") || rawUrl.includes("meli.la")) {
  plataforma = "mercado_livre";
  if (!rawUrl.includes("matt_tool")) {
    const sep = rawUrl.includes("?") ? "&" : "?";
    linkAfiliado = `${rawUrl}${sep}matt_tool=66512398&matt_word=tenisofertas`;
  }
}
// 3. Identificar Shopee
else if (rawUrl.includes("shopee.com")) {
  plataforma = "shopee";
  if (!rawUrl.includes("sub_id=")) {
    const sep = rawUrl.includes("?") ? "&" : "?";
    linkAfiliado = `${rawUrl}${sep}sub_id=whats_tenis`;
  }
}

const precoDe = parseFloat(body.preco_de || body.preco_original || 0);
const precoPor = parseFloat(body.preco_por || body.preco_atual || body.preco || 0);
const tituloOriginal = body.titulo_original || body.titulo || body.nome || "Tênis Esportivo";

// Gerar Hash de Desduplicação
const cleanKey = `${plataforma}:${tituloOriginal.trim().toLowerCase().substring(0, 30)}:${precoPor}`;
let hashVal = 0;
for (let i = 0; i < cleanKey.length; i++) {
  hashVal = ((hashVal << 5) - hashVal) + cleanKey.charCodeAt(i);
  hashVal |= 0;
}
const hashProduto = Math.abs(hashVal).toString(16);

return [{
  json: {
    plataforma,
    categoria: body.categoria || "tenis",
    titulo_original: tituloOriginal,
    preco_de: precoDe,
    preco_por: precoPor,
    cupom: body.cupom || null,
    link_original: rawUrl,
    link_afiliado: linkAfiliado,
    imagem_url: body.imagem_url || "https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=800",
    fonte: body.fonte || "api_afiliado",
    hash_produto: hashProduto,
    status: "pendente"
  }
}];

const items = $input.first().json.results || [];
const out = [];

for (const prod of items) {
  const precoDe = prod.original_price || (prod.price * 1.35);
  const precoPor = prod.price || 0;
  const titulo = prod.title || "";

  if (precoPor >= 50 && precoPor <= 600 && precoDe > precoPor) {
    const cleanKey = `mercado_livre:${titulo.trim().toLowerCase().substring(0, 30)}:${precoPor}`;
    let hashVal = 0;
    for (let i = 0; i < cleanKey.length; i++) {
      hashVal = ((hashVal << 5) - hashVal) + cleanKey.charCodeAt(i);
      hashVal |= 0;
    }
    const hashProduto = Math.abs(hashVal).toString(16);

    out.push({
      json: {
        plataforma: "mercado_livre",
        categoria: "tenis",
        titulo_original: titulo,
        preco_de: parseFloat(precoDe.toFixed(2)),
        preco_por: parseFloat(precoPor.toFixed(2)),
        cupom: null,
        link_original: prod.permalink || "",
        link_afiliado: `${prod.permalink}?matt_tool=66512398&matt_word=tenisofertas`,
        imagem_url: prod.thumbnail ? prod.thumbnail.replace("-I.jpg", "-O.jpg") : null,
        fonte: "api_afiliado",
        hash_produto: hashProduto,
        status: "pendente"
      }
    });
  }
}

return out.length > 0 ? out : [];
